import sys

# 预处理最小素因子 SPF
MAXA = 10**6
spf = list(range(MAXA + 1))
for i in range(2, int(MAXA ** 0.5) + 1):
    if spf[i] == i:
        step = i
        start = i * i
        for x in range(start, MAXA + 1, step):
            if spf[x] == x:
                spf[x] = i

def factor_distinct_primes(x):
    """分解x的不同素因子，使用spf并去重"""
    res = []
    while x > 1:
        p = spf[x]
        res.append(p)
        while x % p == 0:
            x //= p
    # 去重（spf保证递增）
    uniq = []
    last = -1
    for v in res:
        if v != last:
            uniq.append(v)
            last = v
    return uniq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    T = next(it)
    out_lines = []
    for _ in range(T):
        n = next(it)
        arr = [next(it) for __ in range(n)]

        # 统计每个素数出现次数
        cnt = {}
        primes_of = []   # 每个数的素因子集合
        used_primes = [] # 本用例出现过的素数（用于遍历）
        for v in arr:
            ps = factor_distinct_primes(v)
            primes_of.append(ps)
            for p in ps:
                if p not in cnt:
                    cnt[p] = 0
                    used_primes.append(p)
                cnt[p] += 1

        # 尝试找到 0 < cnt[p] < n 的素数
        chosen = -1
        for p in used_primes:
            c = cnt[p]
            if 0 < c < n:
                chosen = p
                break

        b, c = [], []
        if chosen != -1:
            # c 为能被 chosen 整除的数，b 为其余
            for v in arr:
                if v % chosen == 0:
                    c.append(v)
                else:
                    b.append(v)
        else:
            # 所有素数都整除所有数：选最小值入 b，其余入 c
            mn = min(arr)
            b = [mn]
            c = [v for v in arr if v != mn]

        # 输出
        out_lines.append(str(len(b)))
        out_lines.append(" ".join(map(str, b)) if b else "")
        out_lines.append(str(len(c)))
        out_lines.append(" ".join(map(str, c)) if c else "")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

