```java
import java.io.*;
import java.util.*;

/* ACM 风格：主类名 Main，读入输出在 main，核心逻辑放外部函数 */
public class Main {
    static final int MAXA = 1000000;
    static int[] spf = new int[MAXA + 1];

    // 预处理最小素因子
    static void sieve() {
        for (int i = 0; i <= MAXA; i++) spf[i] = i;
        for (int i = 2; i * i <= MAXA; i++) {
            if (spf[i] == i) {
                for (int x = i * i; x <= MAXA; x += i) {
                    if (spf[x] == x) spf[x] = i;
                }
            }
        }
    }

    // 分解为不同素因子（升序且去重）
    static ArrayList<Integer> factorDistinctPrimes(int x) {
        ArrayList<Integer> ps = new ArrayList<>();
        while (x > 1) {
            int p = spf[x];
            ps.add(p);
            while (x % p == 0) x /= p;
        }
        return ps; // 已去重
    }

    public static void main(String[] args) throws Exception {
        sieve();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        StringTokenizer st;

        st = new StringTokenizer(br.readLine());
        int T = Integer.parseInt(st.nextToken());

        while (T-- > 0) {
            // 读 n
            st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            // 读数组
            int[] a = new int[n];
            int idx = 0;
            while (idx < n) {
                st = new StringTokenizer(br.readLine());
                while (st.hasMoreTokens() && idx < n) {
                    a[idx++] = Integer.parseInt(st.nextToken());
                }
            }

            // 统计每个素数出现次数
            HashMap<Integer, Integer> cnt = new HashMap<>();
            ArrayList<ArrayList<Integer>> primesOf = new ArrayList<>(n);
            ArrayList<Integer> used = new ArrayList<>();
            for (int v : a) {
                ArrayList<Integer> ps = factorDistinctPrimes(v);
                primesOf.add(ps);
                for (int p : ps) {
                    Integer c = cnt.get(p);
                    if (c == null) {
                        cnt.put(p, 1);
                        used.add(p);
                    } else {
                        cnt.put(p, c + 1);
                    }
                }
            }

            int chosen = -1;
            for (int p : used) {
                int c = cnt.get(p);
                if (0 < c && c < n) {
                    chosen = p;
                    break;
                }
            }

            ArrayList<Integer> b = new ArrayList<>();
            ArrayList<Integer> c = new ArrayList<>();
            if (chosen != -1) {
                for (int v : a) {
                    if (v % chosen == 0) c.add(v);
                    else b.add(v);
                }
            } else {
                int mn = a[0];
                for (int v : a) mn = Math.min(mn, v);
                b.add(mn);
                for (int v : a) if (v != mn) c.add(v);
            }

            // 输出：先 b，再 c
            out.append(b.size()).append('\n');
            for (int i = 0; i < b.size(); i++) {
                if (i > 0) out.append(' ');
                out.append(b.get(i));
            }
            out.append('\n');
            out.append(c.size()).append('\n');
            for (int i = 0; i < c.size(); i++) {
                if (i > 0) out.append(' ');
                out.append(c.get(i));
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }
}
