const int MAXA = 1000000;
int spf[MAXA + 1]; // 最小素因子

// 预处理最小素因子
void sieve() {
    for (int i = 0; i <= MAXA; ++i) spf[i] = i;
    for (int i = 2; i * i <= MAXA; ++i) {
        if (spf[i] == i) {
            for (int x = i * i; x <= MAXA; x += i) {
                if (spf[x] == x) spf[x] = i;
            }
        }
    }
}

// 分解不同素因子（已去重且升序）
vector<int> factorDistinctPrimes(int x) {
    vector<int> ps;
    while (x > 1) {
        int p = spf[x];
        ps.push_back(p);
        while (x % p == 0) x /= p;
    }
    return ps;
}

int main() {
    ios::sync_with_stdio(false);
